import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { format } from 'date-fns';
import { toast } from 'sonner';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { cn } from '@/lib/utils';
import { SubtleButton } from '@/components/buttons/SubtleButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import ImportIcon from '@/components/icons/file/ImportIcon';
import ArrowBackIcon from '@/components/icons/ArrowBackIcon';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import { Checkbox } from '@/components/ui/checkbox';
import { CustomPagination } from '@/components/carsList/CustomPagination';
import {
    buildCalendarGrid,
    dateKey,
    HolidayRangeRow,
    isSameMonth,
    parseHolidayListRow,
    rangesToDayMap,
} from './holiday-calendar-utils';
import AddHolidayDialog from './AddHolidayDialog';
import UnderlineHeading from '@/components/heading/UnderlineHeading';

const WEEK_DAYS_AR = ['السبت', 'الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة'];

const MONTH_OPTIONS = [
    { label: 'يناير', value: '0' },
    { label: 'فبراير', value: '1' },
    { label: 'مارس', value: '2' },
    { label: 'أبريل', value: '3' },
    { label: 'مايو', value: '4' },
    { label: 'يونيو', value: '5' },
    { label: 'يوليو', value: '6' },
    { label: 'أغسطس', value: '7' },
    { label: 'سبتمبر', value: '8' },
    { label: 'أكتوبر', value: '9' },
    { label: 'نوفمبر', value: '10' },
    { label: 'ديسمبر', value: '11' },
];

function yearOptions(from = 2020, to = 2035) {
    const opts: { label: string; value: string }[] = [];
    for (let y = to; y >= from; y--) {
        opts.push({ label: String(y), value: String(y) });
    }
    return opts;
}

function normalizeListResponse(res: {
    data?: { data?: unknown; pagination?: { total?: number } };
}): { rows: HolidayRangeRow[]; total: number } {
    const top = res?.data?.data as Record<string, unknown> | unknown[] | undefined;
    let raw: unknown[] = [];
    let total = 0;

    if (Array.isArray(top)) {
        raw = top;
        total = raw.length;
    } else if (top && typeof top === 'object') {
        const nested = (top as { data?: unknown }).data;
        if (Array.isArray(nested)) {
            raw = nested;
            const p = (top as { pagination?: { total?: number } }).pagination;
            total = Number(p?.total ?? raw.length);
        }
    }

    const rows = raw
        .map((r) => parseHolidayListRow(r as Record<string, unknown>))
        .filter((x): x is HolidayRangeRow => x != null);

    if (total === 0 && rows.length) {
        total = rows.length;
    }

    return { rows, total };
}

const PAGE_SIZE = 100;

export default function HolidaysList() {
    const now = new Date();
    const [year, setYear] = useState(now.getFullYear());
    const [month0, setMonth0] = useState(now.getMonth());
    const [pageIndex, setPageIndex] = useState(0);
    const [rows, setRows] = useState<HolidayRangeRow[]>([]);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [selectedKeys, setSelectedKeys] = useState<Set<string>>(() => new Set());
    const [addOpen, setAddOpen] = useState(false);
    const [editingHoliday, setEditingHoliday] = useState<HolidayRangeRow | null>(null);
    const importInputRef = useRef<HTMLInputElement>(null);

    const fetchHolidays = useCallback(async () => {
        setIsLoading(true);
        try {
            const response = await apiGet({
                endpoint: endpoints.holidays.list,
                queryParams: {
                    page: pageIndex + 1,
                        pageSize: PAGE_SIZE,
                    year,
                    month: month0 + 1,
                },
            });
            const { rows: nextRows, total } = normalizeListResponse(response);
            setRows(nextRows);
            setTotalCount(total);
        } catch (error) {
            console.error('Error fetching holidays:', error);
            toast.error('تعذر تحميل الإجازات', { className: 'font-cairo' });
            setRows([]);
            setTotalCount(0);
        } finally {
            setIsLoading(false);
        }
    }, [pageIndex, year, month0]);

    useEffect(() => {
        fetchHolidays();
    }, [fetchHolidays]);

    const dayMap = useMemo(() => rangesToDayMap(rows), [rows]);

    const gridDates = useMemo(() => buildCalendarGrid(year, month0), [year, month0]);

    const toggleKey = (key: string) => {
        setSelectedKeys((prev) => {
            const next = new Set(prev);
            if (next.has(key)) next.delete(key);
            else next.add(key);
            return next;
        });
    };

    const exportCsv = () => {
        const lines = ['الاسم,تاريخ'];
        for (const d of gridDates) {
            if (!isSameMonth(d, new Date(year, month0, 1))) continue;
            const k = dateKey(d);
            const h = dayMap.get(k);
            if (h) {
                lines.push(`${h.name.replace(/,/g, ' ')},${k}`);
            }
        }
        const blob = new Blob([lines.join('\n')], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `holidays-${year}-${month0 + 1}.csv`;
        a.click();
        URL.revokeObjectURL(url);
        toast.success('تم تصدير الملف', { className: 'font-cairo' });
    };

    const onImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        e.target.value = '';
        if (!file) return;
        toast.message('استيراد الملف', {
            description: `تم اختيار ${file.name}. ربط الاستيراد بالخادم يتطلب واجهة برمجية مناسبة.`,
            className: 'font-cairo',
        });
    };

    const pageCount = Math.max(1, Math.ceil(totalCount / PAGE_SIZE));
    const startRecord = totalCount === 0 ? 0 : pageIndex * PAGE_SIZE + 1;
    const endRecord = Math.min((pageIndex + 1) * PAGE_SIZE, totalCount);

    return (
        <div>
            <div className='flex flex-wrap items-center justify-end gap-2 sm:gap-3 pt-6'>
                <SubtleButton
                    type="button"
                    onClick={() => importInputRef.current?.click()}
                    className="bg-primery-blue-50 text-sm sm:text-base font-medium text-primery-blue-500 border border-primery-blue-100"
                >
                    <ImportIcon />
                    استيراد ملف بيانات
                </SubtleButton>

            </div>

            <div
                dir="rtl"
                className="mt-6 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A] bg-white-blue-50/40 font-cairo overflow-hidden"
            >
                <input
                    ref={importInputRef}
                    type="file"
                    accept=".csv,.xlsx,.xls"
                    className="hidden"
                    onChange={onImportFile}
                />

                <div className="flex flex-col gap-4 p-4 sm:p-5 border-b border-[#E8E7EA]">
                    <div className="flex flex-col-reverse sm:flex-row sm:items-center sm:justify-between gap-4">
                        <div className="flex flex-wrap items-center justify-between gap-2 w-full">
                            {/* <h2 className="text-xl sm:text-2xl font-bold text-primery-blue-500 text-end">الاجازات</h2> */}
                            <UnderlineHeading text="الاجازات" />
                            <div className='flex md:flex-row flex-col items-center gap-2 sm:gap-3'>
                                <div className="flex flex-wrap items-center justify-end gap-3">
                                    <CustomSelect
                                        value={String(month0)}
                                        onValueChange={(v) => {
                                            if (v === '') return;
                                            setMonth0(Number(v));
                                            setPageIndex(0);
                                        }}
                                        placeholder="شهر"
                                        width="min-w-[140px]"
                                        options={[{ label: 'شهر', value: '' }, ...MONTH_OPTIONS]}
                                    />
                                    <CustomSelect
                                        value={String(year)}
                                        onValueChange={(v) => {
                                            if (v === '') return;
                                            setYear(Number(v));
                                            setPageIndex(0);
                                        }}
                                        placeholder="سنة"
                                        width="min-w-[120px]"
                                        options={[{ label: 'سنة', value: '' }, ...yearOptions()]}
                                    />
                                </div>
                                <PrimaryButton
                                    type="button"
                                    className="text-sm sm:text-base px-[14px] py-2 font-semibold"
                                    onClick={() => {
                                        setEditingHoliday(null);
                                        setAddOpen(true);
                                    }}
                                >
                                    إنشاء اجازة
                                </PrimaryButton>
                                <button
                                    type="button"
                                    onClick={exportCsv}
                                    className="flex items-center justify-center gap-2 px-[14px] py-2 bg-primery-blue-50 border border-primery-blue-50 hover:bg-primery-blue-100 rounded-lg shadow-[0px_1px_2px_0px_#1018280D]"
                                    aria-label="تصدير"
                                >
                                    <ArrowBackIcon className="text-primery-blue-700" />
                                </button>

                            </div>
                        </div>
                    </div>


                </div>

                <div className="p-3 sm:p-4">
                    <div className="grid grid-cols-7 gap-2 sm:gap-3 mb-2">
                        {WEEK_DAYS_AR.map((label) => (
                            <div
                                key={label}
                                className="text-center text-xs sm:text-sm font-semibold text-primery-blue-500 py-2"
                            >
                                {label}
                            </div>
                        ))}
                    </div>

                    <div
                        className={cn(
                            'grid grid-cols-7 gap-2 sm:gap-3 auto-rows-fr',
                            isLoading && 'opacity-60 pointer-events-none',
                        )}
                    >
                        {gridDates.map((d) => {
                            const k = dateKey(d);
                            const inMonth = isSameMonth(d, new Date(year, month0, 1));
                            const holiday = inMonth ? dayMap.get(k) : undefined;
                            const dayNum = d.getDate();

                            return (
                                <div
                                    key={k}
                                    role={inMonth && holiday ? 'button' : undefined}
                                    tabIndex={inMonth && holiday ? 0 : undefined}
                                    onClick={() => {
                                        if (!inMonth || !holiday) return;
                                        const row = rows.find((r) => r.id === holiday.id);
                                        if (row) {
                                            setEditingHoliday(row);
                                            setAddOpen(true);
                                        }
                                    }}
                                    onKeyDown={(e) => {
                                        if (!inMonth || !holiday) return;
                                        if (e.key === 'Enter' || e.key === ' ') {
                                            e.preventDefault();
                                            const row = rows.find((r) => r.id === holiday.id);
                                            if (row) {
                                                setEditingHoliday(row);
                                                setAddOpen(true);
                                            }
                                        }
                                    }}
                                    title={inMonth && holiday ? 'اضغط للتعديل' : undefined}
                                    className={cn(
                                        'min-h-[120px] sm:min-h-[140px] rounded-lg border bg-white p-2 sm:p-3 flex flex-col shadow-sm',
                                        inMonth ? 'border-[#E0E4EB]' : 'border-dashed border-[#E8E7EA] bg-[#FAFAFB]',
                                        inMonth && holiday && 'cursor-pointer hover:border-primery-blue-300 hover:shadow-md transition-shadow',
                                    )}
                                >
                                    <div className="flex flex-row-reverse items-start justify-between gap-1 mb-2">
                                        <span className="text-sm font-semibold text-primery-blue-900 tabular-nums">
                                            {inMonth ? dayNum : ''}
                                        </span>
                                        {inMonth && (
                                            <div
                                                onClick={(e) => e.stopPropagation()}
                                                onKeyDown={(e) => e.stopPropagation()}
                                                className="inline-flex"
                                            >
                                                <Checkbox
                                                    checked={selectedKeys.has(k)}
                                                    onCheckedChange={() => toggleKey(k)}
                                                    aria-label={`تحديد ${k}`}
                                                    className="border-primery-blue-300 data-[state=checked]:bg-primery-blue-600"
                                                />
                                            </div>
                                        )}
                                    </div>

                                    {inMonth && holiday ? (
                                        <div className="mt-auto space-y-2 text-end">
                                            <p className="text-[11px] sm:text-xs text-[#625E74]">
                                                التاريخ: {format(d, 'yyyy/MM/dd')}
                                            </p>
                                            <p className="text-xs sm:text-sm font-semibold text-amber-600 leading-snug break-words">
                                                {holiday.name}
                                            </p>
                                        </div>
                                    ) : inMonth ? (
                                        <div className="mt-auto">
                                            <span className="inline-block w-full text-center text-xs text-[#9CA3AF] bg-[#F3F4F6] rounded-md py-2 px-1 border border-[#E5E7EB]">
                                                غير مفعل
                                            </span>
                                        </div>
                                    ) : null}
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 px-4 py-3 border-t border-[#E8E7EA] bg-white">
                    <p className="text-center sm:text-end font-normal text-primery-blue-600 text-sm sm:text-base">
                        {totalCount === 0 ? 'لا توجد سجلات' : `عرض ${startRecord} الى ${endRecord} من ${totalCount}`}
                    </p>
                    {pageCount > 1 && (
                        <CustomPagination
                            totalItems={totalCount}
                            itemsPerPage={PAGE_SIZE}
                            currentPage={pageIndex + 1}
                            onPageChange={(p) => setPageIndex(p - 1)}
                        />
                    )}
                </div>
            </div>

            <AddHolidayDialog
                open={addOpen}
                onOpenChange={(o) => {
                    setAddOpen(o);
                    if (!o) setEditingHoliday(null);
                }}
                onSaved={fetchHolidays}
                editingHoliday={editingHoliday}
            />
        </div>
    );
}
