import { ColumnDef, Row } from '@tanstack/react-table';
import EditIcon from '@/components/icons/EditIcon';
import { Link } from 'react-router-dom';
import { shiftInfo } from '../../types/shift.types';
import { dayActive } from '../../forms/addShift/shiftFormUtils';

const WEEKDAY_LABELS: Record<string, string> = {
    sunday: 'الأحد',
    monday: 'الإثنين',
    tuesday: 'الثلاثاء',
    wednesday: 'الأربعاء',
    thursday: 'الخميس',
    friday: 'الجمعة',
    saturday: 'السبت',
};

function formatWeekdaysSummary(row: shiftInfo): string {
    const keys = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'] as const;
    const active = keys.filter((k) => dayActive(row[k]));
    if (active.length === 0) return '—';
    return active.map((k) => WEEKDAY_LABELS[k]).join('، ');
}

function formatShiftTypeLabel(type: string | null | undefined): string {
    if (type === 'am') return 'صباحى';
    if (type === 'pm') return 'مسائى';
    return type || '—';
}

function formatTimeCell(v: string | null | undefined): string {
    if (v == null || v === '') return '—';
    const m = String(v).match(/(\d{2}):(\d{2})/);
    return m ? `${m[1]}:${m[2]}` : String(v);
}

const ActionsCell = ({ row }: { row: Row<shiftInfo> }) => {
    return (
        <div className="cursor-pointer flex justify-center">
            <Link to={`/human-resources/shifts/${row.original.id}/edit`}>
                <EditIcon className="text-primery-blue-400" />
            </Link>
        </div>
    );
};

export const columns: ColumnDef<shiftInfo>[] = [
    {
        accessorKey: 'name',
        header: () => (
            <div className="text-nowrap text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                الاسم
            </div>
        ),
        cell: ({ row }) => (
            <div className="flex flex-row justify-start items-center gap-4 text-nowrap text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                <div className="flex flex-col gap-1">
                    <p className="tracking-normal text-primery-blue-900 font-medium text-sm">{row.original.name}</p>
                </div>
            </div>
        ),
    },
    {
        id: 'weekdays',
        header: () => (
            <div className="text-nowrap text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                أيام العمل
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 text-[#625E74] font-normal tracking-normal leading-[26.4px] max-w-[220px] whitespace-normal">
                {formatWeekdaysSummary(row.original)}
            </div>
        ),
    },
    {
        accessorKey: 'type',
        header: () => (
            <div className="text-nowrap text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                نوع الوردية
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {formatShiftTypeLabel(row.original.type)}
            </div>
        ),
    },
    {
        accessorKey: 'shift_start_time',
        header: () => (
            <div className="text-nowrap text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                بداية الوردية
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {formatTimeCell(row.original.shift_start_time)}
            </div>
        ),
    },
    {
        accessorKey: 'shift_end_time',
        header: () => (
            <div className="text-nowrap text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                نهاية الوردية
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {formatTimeCell(row.original.shift_end_time)}
            </div>
        ),
    },
    {
        accessorKey: 'early_entry_time',
        header: () => (
            <div className="text-nowrap text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                بداية تسجيل الدخول
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {formatTimeCell(row.original.early_entry_time)}
            </div>
        ),
    },
    {
        accessorKey: 'late_entry_time',
        header: () => (
            <div className="text-nowrap text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                نهاية تسجيل الدخول
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                {formatTimeCell(row.original.late_entry_time)}
            </div>
        ),
    },
    {
        id: 'actions',
        header: () => (
            <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                تعديل
            </div>
        ),
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
